// Test shim of three.js's STLLoader.parse (r170, MIT): binary STL (and plain
// ASCII STL) to a non-indexed BufferGeometry with position and normal.
import { BufferGeometry, BufferAttribute } from '../../index.mjs';

export class STLLoader {
  parse(data) {
    const u8 = data instanceof ArrayBuffer ? new Uint8Array(data) : new Uint8Array(data.buffer, data.byteOffset, data.byteLength);
    const view = new DataView(u8.buffer, u8.byteOffset, u8.byteLength);
    const g = new BufferGeometry();
    if (u8.byteLength >= 84 && 84 + view.getUint32(80, true) * 50 === u8.byteLength) {
      const n = view.getUint32(80, true);
      const pos = new Float32Array(n * 9), nor = new Float32Array(n * 9);
      for (let f = 0; f < n; f++) {
        const s = 84 + f * 50;
        const nx = view.getFloat32(s, true), ny = view.getFloat32(s + 4, true), nz = view.getFloat32(s + 8, true);
        for (let i = 0; i < 3; i++) {
          const o = s + 12 + i * 12, k = f * 9 + i * 3;
          pos[k] = view.getFloat32(o, true); pos[k + 1] = view.getFloat32(o + 4, true); pos[k + 2] = view.getFloat32(o + 8, true);
          nor[k] = nx; nor[k + 1] = ny; nor[k + 2] = nz;
        }
      }
      g.setAttribute('position', new BufferAttribute(pos, 3));
      g.setAttribute('normal', new BufferAttribute(nor, 3));
      return g;
    }
    const text = new TextDecoder().decode(u8);
    const num = '[-+]?(?:\\d+\\.?\\d*|\\.\\d+)(?:[eE][-+]?\\d+)?';
    const re = new RegExp(`vertex\\s+(${num})\\s+(${num})\\s+(${num})`, 'g');
    const pos = [];
    for (const m of text.matchAll(re)) pos.push(+m[1], +m[2], +m[3]);
    g.setAttribute('position', new BufferAttribute(new Float32Array(pos), 3));
    g.computeVertexNormals();
    return g;
  }
}
